package calc

import (
	"math/rand"
	"testing"
)

func TestHuntA_PercentZeroTotal(t *testing.T) {
	for _, part := range []int{0, 1, 7} {
		if got := Percent(part, 0); got != 0 {
			t.Fatalf("Percent(%d, 0) = %d, want 0", part, got)
		}
	}
}

func TestHuntA_PercentWithinRange(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	for i := 0; i < 500; i++ {
		total := 1 + r.Intn(1000)
		part := r.Intn(total + 1)
		got := Percent(part, total)
		if got < 0 || got > 100 || (part == total && got != 100) || (part == 0 && got != 0) {
			t.Fatalf("Percent(%d, %d) = %d", part, total, got)
		}
	}
}
